import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(
    const float* input,
    const float* gamma,
    const float* beta,
    const float* mul_weight,
    float* output,
    int batch_size,
    int num_channels,
    int num_groups,
    float eps) {

    int batch_idx = blockIdx.x;
    int group_idx = blockIdx.y;
    int group_size = num_channels / num_groups;
    int channel_idx = group_idx * group_size + threadIdx.x;

    if (batch_idx >= batch_size || channel_idx >= num_channels) return;

    extern __shared__ float smem[];
    float* sum = smem;
    float* sum_sq = smem + group_size;

    float x = input[batch_idx * num_channels + channel_idx];
    sum[threadIdx.x] = x;
    sum_sq[threadIdx.x] = x * x;
    __syncthreads();

    // Parallel reduction
    for (int stride = group_size/2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sum[threadIdx.x] += sum[threadIdx.x + stride];
            sum_sq[threadIdx.x] += sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float mean = sum[0] / group_size;
    float var = (sum_sq[0]/group_size) - (mean*mean);

    // Normalization
    float norm = (x - mean) / sqrtf(var + eps);
    norm = norm * gamma[channel_idx] + beta[channel_idx];

    // Swish -> Mul -> Swish
    float swish1 = norm * (1.0f / (1.0f + __expf(-norm)));
    float mul = swish1 * mul_weight[channel_idx];
    float swish2 = mul * (1.0f / (1.0f + __expf(-mul)));

    output[batch_idx * num_channels + channel_idx] = swish2;
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor mul_weight,
    int num_groups,
    float eps) {

    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_channels = input.size(1);
    int group_size = num_channels / num_groups;

    dim3 grid(batch_size, num_groups);
    dim3 block(group_size);
    size_t smem = 2 * group_size * sizeof(float);

    fused_op_kernel<<<grid, block, smem>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        mul_weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_channels,
        num_groups,
        eps
    );

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor mul_weight,
    int num_groups,
    float eps);
"""

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, multiply_weight_shape):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.num_groups = num_groups
        self.eps = 1e-5
        self.gamma = nn.Parameter(torch.ones(out_features))
        self.beta = nn.Parameter(torch.zeros(out_features))
        self.multiply_weight = nn.Parameter(torch.randn(multiply_weight_shape))

    def forward(self, x):
        x = self.gemm(x)
        x = fused_op.fused_op_cuda(
            x, self.gamma, self.beta, self.multiply_weight, 
            self.num_groups, self.eps
        )
        return x
